/* Câu chép chính tả: khung phát (giây) trong audio từng part. Câu cũ căn tay 21/10/2026; câu thêm 25/10/2026 lấy theo mốc lời thoại (sync.js), mỗi câu đã được nghe lại và đối chiếu lời thoại. */
window.CAMDICT={"1":{"1":[{"s":93.63,"e":94.63,"t":"My name’s Jan."},{"s":94.68,"e":99.8,"t":"Are you the right person to talk to about the Buckworth Conservation Group?"},{"s":99.91,"e":101.04,"t":"Yes, I’m Peter."},{"s":101.15,"e":102.28,"t":"I’m the secretary."},{"s":102.8,"e":108.33,"t":"I’ve just moved to this area, and I’m interested in getting involved."},{"s":108.73,"e":111.59,"t":"I was in a similar group where I used to live."},{"s":111.53,"e":115.05,"t":"Could you tell me something about your activities, please?"},{"s":116.13,"e":120.06,"t":"Well, we have a mixture of regular activities and special events."},{"s":120.4,"e":124.05,"t":"One of the regular ones is trying to keep the beach free of litter."},{"s":123.96,"e":129.56,"t":"A few of us spend a couple of hours a month on it, and it’s awful how much there is to clear."},{"s":129.84,"e":133.17,"t":"I wish people would be more responsible and take it home with them."},{"s":133.26,"e":134.82,"t":"I totally agree."},{"s":134.87,"e":137.28,"t":"I’d be happy to help with that."},{"s":137.34,"e":139.4,"t":"Is it OK to take dogs?"},{"s":139.49,"e":142.74,"t":"I’m afraid not, as they’re banned from the beach itself."},{"s":142.97,"e":145.22,"t":"You can take them along the cliffs, though."},{"s":145.26,"e":146.94,"t":"And children are welcome."},{"s":147.38,"e":152.36,"t":"We also manage a nature reserve, and there’s a lot to do there all year round."},{"s":152.56,"e":161.09,"t":"For example, because it’s a popular place to visit, we spend a lot of time looking after the paths and making sure they’re in good condition for walking."},{"s":161.2,"e":163.55,"t":"I could certainly help with that."},{"s":164.73,"e":168.05,"t":"And we have a programme of creating new habitats there."},{"s":168.32,"e":179.5,"t":"We’ve just finished making and installing nesting boxes for birds to use, and next we’re going to work on encouraging insects – they’re important for the biodiversity of the reserve."},{"s":180.67,"e":187.81,"t":"Oh, and we’re also running a project to identify the different species of butterflies that visit the reserve."},{"s":187.99,"e":190.49,"t":"You might be interested in taking part in that."},{"s":191.74,"e":197.59,"t":"I was involved in something similar where I used to live, counting all the species of moths."},{"s":197.62,"e":198.59,"t":"I’d enjoy that."},{"s":198.63,"e":206.62,"t":"Another job we’re doing at the reserve is replacing the wall on the southern side, between the parking area and our woodshed."},{"s":261.05,"e":266.47,"t":"I’d like to get to know the local countryside, as I’m new to the area."},{"s":266.45,"e":267.4,"t":"Yes, we do."},{"s":267.29,"e":271.41,"t":"The next walk is to Ruston Island, a week on Saturday."},{"s":271.42,"e":280.11,"t":"We’ll be meeting in the car park at Dunsmore Beach at low tide – that’s when the sands are dry enough for us to walk to the island without getting wet."},{"s":281.61,"e":284.19,"t":"The island’s a great place to explore."},{"s":284.11,"e":287.43,"t":"It’s quite small, and it’s got a range of habitats."},{"s":287.61,"e":293.25,"t":"It’s also an ideal location for seeing seals just off the coast, or even on the beach."},{"s":293.9,"e":299.46,"t":"And is there anything we should bring, like a picnic, for instance?"},{"s":299.63,"e":303.15,"t":"Yes, do bring one, as it’s a full-day walk."},{"s":303.6,"e":309.39,"t":"And of course it’ll be wet walking across and back, so make sure your boots are waterproof."},{"s":309.06,"e":313.62,"t":"I must buy a new pair – there’s a hole in one of my current ones!"},{"s":313.71,"e":317.81,"t":"Well, I’d definitely like to come on the walk."},{"s":323.9,"e":325.79,"t":"I’ve never tried that before."},{"s":325.89,"e":328.97,"t":"Is it OK for beginners to take part?"},{"s":329.46,"e":337.54,"t":"There’ll be a couple of experts leading the session, and we keep the number of participants down, so you’ll get as much help as you need."},{"s":338.1,"e":341.4,"t":"I’d love to be able to make chairs."},{"s":341.73,"e":344.13,"t":"That’s probably too ambitious for one day!"},{"s":344.22,"e":349.77,"t":"You’ll be starting with wooden spoons, and of course learning how to use the tools."},{"s":350.04,"e":353.07,"t":"And anything you make is yours to take home with you."},{"s":367.87,"e":370.99,"t":"I should think I’ll come home the same day."},{"s":371.04,"e":373.79,"t":"Well, I’d certainly like to join the group."}],"2":[{"s":60.54,"e":69.21,"t":"My name’s Lou Miller and I’m going to be your tour guide today as we take this fantastic boat trip around the Tasmanian coast."},{"s":69.57,"e":74.37,"t":"Before we set off, I just want to tell you a few things about our journey."},{"s":74.5,"e":77.62,"t":"Our boats aren’t huge as you can see."},{"s":77.74,"e":88.81,"t":"We already have three staff members on board and on top of that, we can transport a further fifteen people – that’s you – around the coastline."},{"s":89.07,"e":100.19,"t":"But please note if there are more than nine people on either side of the boat, we’ll move some of you over, otherwise all eighteen of us will end up in the sea!"},{"s":100.42,"e":103.2,"t":"We’ve recently upgraded all our boats."},{"s":103.2,"e":115.72,"t":"They used to be jet black, but our new ones now have these comfortable dark red seats and a light-green exterior in order to stand out from others and help promote our company."},{"s":115.8,"e":120.22,"t":"This gives our boats a rather unique appearance, don’t you think?"},{"s":120.38,"e":126.05,"t":"We offer you a free lunchbox during the trip and we have three types."},{"s":126.39,"e":130.31,"t":"Lunchbox 1 contains ham and tomato sandwiches."},{"s":130.62,"e":140.85,"t":"Lunchbox 2 contains a cheddar cheese roll and Lunchbox 3 is salad-based and also contains eggs and tuna."},{"s":141.03,"e":146.67,"t":"All three lunchboxes also have a packet of crisps and chocolate bar inside."},{"s":146.89,"e":150.75,"t":"Please let staff know which lunchbox you prefer."},{"s":151.57,"e":156.38,"t":"I’m sure I don’t have to ask you not to throw anything into the sea."},{"s":156.61,"e":168.5,"t":"We don’t have any bins to put litter in, but Jess, myself or Ray, our other guide, will collect it from you after lunch and put it all in a large plastic sack."},{"s":223.8,"e":231.84,"t":"This area is famous for its ancient lighthouse, which you’ll see from the boat as we turn past the first little island."},{"s":232.29,"e":240.45,"t":"It was built in 1838 to protect sailors as a number of shipwrecks had led to significant loss of life."},{"s":240.96,"e":248.12,"t":"The construction itself was complicated as some of the original drawings kept by the local council show."},{"s":248.32,"e":253.44,"t":"It sits right on top of the cliffs in a very isolated spot."},{"s":254.18,"e":266.24,"t":"In the nineteenth century there were many jobs there, such as polishing the brass lamps, chopping firewood and cleaning windows, that kept lighthouse keepers busy."},{"s":266.91,"e":277.67,"t":"These workers were mainly prison convicts until the middle of that century when ordinary families willing to live in such circumstances took over."},{"s":278.08,"e":282.08,"t":"Some of you have asked me what creatures we can expect to see."},{"s":299.31,"e":307.66,"t":"When we get to the rocky area inhabited by fur seals, we’ll stop and watch them swimming around the coast."},{"s":308.0,"e":314.96,"t":"They’re inquisitive creatures so don’t be surprised if one pops up right in front of you."},{"s":322.35,"e":330.03,"t":"Dolphins, on the other hand, can sometimes approach on their own or in groups as they ride the waves beside us."},{"s":331.38,"e":334.25,"t":"Lastly, I want to mention the caves."},{"s":334.47,"e":343.16,"t":"Tasmania is famous for its caves and the ones we’ll pass by are so amazing that people are lost for words when they see them."}],"3":[{"s":68.78,"e":73.99,"t":"So, Tim, we have to do a short summary of our work experience on a farm."},{"s":74.83,"e":80.07,"t":"My farm was great, but arranging the work experience was hard."},{"s":80.45,"e":84.12,"t":"One problem was it was miles away and I don’t drive."},{"s":84.45,"e":89.99,"t":"And also, I’d really wanted a placement for a month, but I could only get one for two weeks."},{"s":90.36,"e":95.94,"t":"I was lucky, the farmer let me stay on the farm so I didn’t have to travel."},{"s":96.29,"e":100.62,"t":"But finding the right sort of farm to apply to wasn’t easy."},{"s":100.63,"e":103.95,"t":"No, they don’t seem to have websites, do they."},{"s":104.04,"e":107.46,"t":"I found mine through a friend of my mother’s, but it wasn’t easy."},{"s":109.11,"e":112.77,"t":"My farm was mostly livestock, especially sheep."},{"s":112.85,"e":115.27,"t":"I really enjoyed helping out with them."},{"s":120.1,"e":123.42,"t":"No, the farmer was there, and he told me what to do."},{"s":124.11,"e":127.44,"t":"It wasn’t a straightforward birth, but I managed."},{"s":136.16,"e":144.98,"t":"Then another time a lamb had broken its leg, and they got the vet in to set it, and he talked me through what he was doing."},{"s":145.16,"e":146.64,"t":"That was really useful."},{"s":146.71,"e":148.88,"t":"Yes, my farm had sheep too."},{"s":148.95,"e":158.16,"t":"The farm was in a valley and they had a lowland breed called Suffolks, although the farmer said they’d had other breeds in the past."},{"s":158.16,"e":160.66,"t":"So were they bred for their meat?"},{"s":161.76,"e":163.92,"t":"They’re quite big and solid."},{"s":164.08,"e":169.48,"t":"My farm was up in the hills and they had a different breed of sheep, they were Cheviots."},{"s":177.63,"e":182.15,"t":"I was interested in the amount of supplements they add to animals’ feed nowadays."},{"s":182.46,"e":187.54,"t":"Like, even the chickens got extra vitamins and electrolytes in their feed."},{"s":187.64,"e":189.56,"t":"Yes, I found that too."},{"s":189.66,"e":191.17,"t":"And they’re not cheap."},{"s":191.28,"e":195.64,"t":"But my farmer said some are overpriced for what they are."},{"s":195.68,"e":202.0,"t":"And he didn’t give them as a matter of routine, just at times when the chickens seemed to particularly require them."},{"s":202.11,"e":203.82,"t":"Yes, mine said the same."},{"s":204.03,"e":212.52,"t":"He said certain breeds of chickens might need more supplements than the others, but the cheap and expensive ones are all basically the same."},{"s":213.02,"e":217.0,"t":"So did your farm have any other livestock, Diana?"},{"s":225.56,"e":235.19,"t":"Some cows had been treated with antibiotics, so their milk wasn’t suitable for human consumption, and it had to be put in a separate container."},{"s":235.22,"e":244.45,"t":"But I got mixed up, and I poured some milk from the wrong cow in with the milk for humans, so the whole lot had to be thrown away."},{"s":244.53,"e":247.13,"t":"The farmer wasn’t too happy with me."},{"s":247.22,"e":252.13,"t":"I asked my farmer how much he depended on the vet to deal with health problems."},{"s":252.22,"e":260.04,"t":"I’d read reports that the livestock’s health is being affected as farmers are under pressure to increase production."},{"s":260.38,"e":270.07,"t":"Well, he didn’t agree with that, but he said that actually some of the stuff the vets do, like minor operations, he’d be quite capable of doing himself."},{"s":270.59,"e":272.62,"t":"My farmer said the same."},{"s":313.48,"e":319.74,"t":"Now we’ve got to give a bit of feedback about last term’s modules – just short comments, apparently."},{"s":319.92,"e":322.14,"t":"Shall we do that now?"},{"s":322.8,"e":324.93,"t":"So medical terminology."},{"s":324.92,"e":330.99,"t":"Well, my heart sank when I saw that, especially right at the beginning of the course."},{"s":331.13,"e":333.67,"t":"And I did struggle with it."},{"s":333.82,"e":339.04,"t":"I’d thought it’d be hard, but actually I found it all quite straightforward."},{"s":339.07,"e":342.02,"t":"What did you think about diet and nutrition?"},{"s":343.61,"e":351.23,"t":"Do you remember what they told us about pet food and the fact that there’s such limited checking into whether or not it’s contaminated?"},{"s":351.63,"e":356.34,"t":"I mean in comparison with the checks on food for humans – I thought that was terrible."},{"s":356.96,"e":369.93,"t":"I think the module that really impressed me was the animal disease one, when we looked at domesticated animals in different parts of the world, like camels and water buffalo and alpaca."},{"s":370.13,"e":378.25,"t":"The economies of so many countries depend on these, but scientists don’t know much about the diseases that affect them."},{"s":378.26,"e":385.59,"t":"Yes, I thought they’d know a lot about ways of controlling and eradicating those diseases, but that’s not the case at all."},{"s":385.59,"e":388.65,"t":"I loved the wildlife medication unit."},{"s":388.96,"e":393.08,"t":"Things like helping birds that have been caught in oil spills."},{"s":393.04,"e":395.33,"t":"That’s something I hadn’t thought about before."},{"s":395.35,"e":400.02,"t":"Yeah, I thought I might write my dissertation on something connected with that."}],"4":[{"s":87.23,"e":95.59,"t":"There are various designs of labyrinth but what they all have in common is a winding spiral path which leads to a central area."},{"s":96.63,"e":101.79,"t":"There is one starting point at the entrance and the goal is to reach the central area."},{"s":102.58,"e":112.48,"t":"Finding your way through a labyrinth involves many twists and turns, but it’s not possible to get lost as there is only one single path."},{"s":113.22,"e":120.55,"t":"In modern times, the word labyrinth has taken on a different meaning and is often used as a synonym for a maze."},{"s":120.82,"e":127.93,"t":"A maze is quite different as it is a kind of puzzle with an intricate network of paths."},{"s":128.39,"e":137.06,"t":"Mazes became fashionable in the 15th and 16th centuries in Europe, and can still be found in the gardens of great houses and palaces."},{"s":137.81,"e":143.85,"t":"The paths are usually surrounded by thick, high hedges so that it’s not possible to see over them."},{"s":143.95,"e":153.89,"t":"Entering a maze usually involves getting lost a few times before using logic to work out the pattern and find your way to the centre and then out again."},{"s":154.98,"e":159.25,"t":"There are lots of dead ends and paths which lead you back to where you started."},{"s":160.57,"e":165.6,"t":"The word ‘maze’ is believed to come from a Scandinavian word for a state of confusion."},{"s":166.26,"e":169.26,"t":"This is where the word ‘amazing’ comes from."},{"s":169.39,"e":174.58,"t":"Labyrinths, on the other hand, have a very different function."},{"s":175.41,"e":183.48,"t":"Although people now often refer to things they find complicated as labyrinths, this is not how they were seen in the past."},{"s":184.05,"e":190.62,"t":"The winding spiral of the labyrinth has been used for centuries as a metaphor for life’s journey."},{"s":191.31,"e":199.28,"t":"It served as a spiritual reminder that there is purpose and meaning to our lives and helped to give people a sense of direction."},{"s":199.46,"e":209.19,"t":"Labyrinths are thought to encourage a feeling of calm and have been used as a meditation and prayer tool in many cultures over many centuries."},{"s":210.17,"e":221.31,"t":"The earliest examples of the labyrinth spiral pattern have been found carved into stone, from Sardinia to Scandinavia, from Arizona to India to Africa."},{"s":222.27,"e":226.59,"t":"In Europe, these spiral carvings date from the late Bronze Age."},{"s":227.02,"e":235.16,"t":"The Native American Pima tribe wove baskets with a circular labyrinth design that depicted their own cosmology."},{"s":235.89,"e":242.28,"t":"In Ancient Greece, the labyrinth spiral was used on coins around four thousand years ago."},{"s":242.79,"e":250.21,"t":"Labyrinths made of mosaics were commonly found in bathhouses, villas and tombs throughout the Roman Empire."},{"s":251.53,"e":256.59,"t":"In Northern Europe, there were actual physical labyrinths designed for walking on."},{"s":257.51,"e":261.88,"t":"These were cut into the turf or grass, usually in a circular pattern."},{"s":262.48,"e":271.21,"t":"The origin of these walking labyrinths remains unclear, but they were probably used for fertility rites which may date back thousands of years."},{"s":286.96,"e":290.71,"t":"More recently labyrinths have experienced something of a revival."},{"s":291.12,"e":304.04,"t":"Some believe that walking a labyrinth promotes healing and mindfulness, and there are those who believe in its emotional and physical benefits, which include slower breathing and a restored sense of balance and perspective."},{"s":304.98,"e":314.22,"t":"This idea has become so popular that labyrinths have been laid into the floors of spas, wellness centres and even prisons in recent years."},{"s":314.64,"e":324.9,"t":"A pamphlet at Colorado Children’s Hospital informs patients that ‘walking a labyrinth can often calm people in the midst of a crisis’."},{"s":325.83,"e":328.83,"t":"And apparently, it’s not only patients who benefit."},{"s":329.31,"e":335.04,"t":"Many visitors find walking a labyrinth less stressful than sitting in a corridor or waiting room."},{"s":335.67,"e":338.93,"t":"Some doctors even walk the labyrinth during their breaks."},{"s":339.72,"e":346.47,"t":"In some hospitals, patients who can’t walk can have a paper ‘finger labyrinth’ brought to their bed."},{"s":346.63,"e":354.92,"t":"The science behind the theory is a little sketchy, but there are dozens of small-scale studies which support claims about the benefits of labyrinths."},{"s":355.17,"e":364.98,"t":"For example, one study found that walking a labyrinth provided ‘short-term calming, relaxation, and relief from anxiety’ for Alzheimer’s patients."},{"s":365.84,"e":369.43,"t":"So, what is it about labyrinths that makes their appeal so universal?"}]},"2":{"1":[{"s":94.65,"e":95.81,"t":"Oh, good morning."},{"s":95.92,"e":97.6,"t":"My name’s Frank Pritchard."},{"s":97.73,"e":100.39,"t":"I’ve just retired and moved to Southoe."},{"s":100.64,"e":106.75,"t":"I’d like to become a volunteer, and I gather you co-ordinate voluntary work in the village."},{"s":108.24,"e":110.19,"t":"What sort of thing could I do?"},{"s":110.58,"e":113.47,"t":"Well, we need help with the village library."},{"s":113.54,"e":118.99,"t":"We borrow books from the town library, and individuals also donate them."},{"s":119.08,"e":126.48,"t":"So, one thing you could do is get involved in collecting them – if you’ve got a car, that is."},{"s":126.55,"e":128.36,"t":"Yes, that’s no problem."},{"s":128.64,"e":133.93,"t":"The times are pretty flexible so we can arrange it to suit you."},{"s":134.05,"e":142.43,"t":"Another thing is the records that we keep of the books we’re given, and those we borrow and need to return to the town library."},{"s":142.56,"e":147.27,"t":"It would be very useful to have another person to help keep them up to date."},{"s":148.71,"e":153.01,"t":"I’m used to working on a computer – I presume they’re computerised?"},{"s":160.35,"e":165.68,"t":"No, we simply have the use of a room in the village hall, the West Room."},{"s":165.68,"e":168.07,"t":"It’s on the left as you go in."},{"s":168.07,"e":170.85,"t":"I must go and have a look inside the hall."},{"s":171.07,"e":173.44,"t":"Yes, it’s a nice building."},{"s":173.66,"e":177.23,"t":"Do you run a lunch club in the village for elderly people?"},{"s":177.27,"e":179.45,"t":"I know a lot of places do."},{"s":179.79,"e":182.73,"t":"Yes, we have a very successful club."},{"s":183.08,"e":186.22,"t":"I could help with transport, if that’s of any use."},{"s":188.07,"e":193.98,"t":"People come to the club from neighbouring villages, and we’re always in need of more drivers."},{"s":194.42,"e":199.08,"t":"And does the club have groups that focus on a particular hobby, too?"},{"s":199.53,"e":205.08,"t":"I could get involved in one or two, particularly if there are any art groups."},{"s":206.44,"e":210.71,"t":"I’ll find out where we need help and get back to you."},{"s":211.29,"e":214.94,"t":"What about help for individual residents."},{"s":214.89,"e":217.26,"t":"Do you arrange that at all?"},{"s":217.39,"e":220.28,"t":"Yes, we do it as a one-off."},{"s":220.42,"e":223.09,"t":"In fact, there’s Mrs Carroll."},{"s":223.17,"e":228.75,"t":"She needs a lift to the hospital next week, and we’re struggling to find someone."},{"s":228.83,"e":230.54,"t":"When’s her appointment?"},{"s":232.05,"e":234.15,"t":"It would take the whole morning."},{"s":234.38,"e":235.56,"t":"I could do that."},{"s":235.57,"e":237.44,"t":"Oh, that would be great."},{"s":238.35,"e":248.61,"t":"And also, next week, we’re arranging to have some work done to Mr Selsbury’s house before he moves, as he isn’t healthy enough to do it himself."},{"s":248.79,"e":257.07,"t":"We’ve got some people to decorate his kitchen, but if you could do some weeding in his garden, that would be wonderful."},{"s":259.29,"e":262.99,"t":"And presumably the day and time are flexible."},{"s":300.73,"e":308.35,"t":"The volunteers group also organises monthly social events, which is a great way to meet other people, of course."},{"s":309.27,"e":322.11,"t":"So next month, on the 19th of October, we’re holding a quiz – a couple of residents are great at planning unusual ones, and we always fill the village hall."},{"s":322.13,"e":323.74,"t":"That sounds like fun."},{"s":324,"e":325.74,"t":"Can I do anything to help?"},{"s":326.04,"e":332.67,"t":"Well, because of the number of people, we need plenty of refreshments for halfway through."},{"s":332.82,"e":336.33,"t":"So, if you could provide any, we’d be grateful."},{"s":336.44,"e":338.02,"t":"I’m sure I could."},{"s":338.18,"e":340.92,"t":"I’ll think about what to make, and let you know."},{"s":342.19,"e":348.72,"t":"Then on November the 18th, we’re holding a dance, also in the village hall."},{"s":348.85,"e":359.31,"t":"We’ve booked a band that specialises in music of the 1930s – they’ve been before, and we’ve had a lot of requests to bring them back."},{"s":359.67,"e":363.9,"t":"I’m not really a dancer, but I’d like to do something to help."},{"s":364.25,"e":377.07,"t":"Well, we sell tickets in advance, and having an extra person to check them at the door, as people arrive, would be good – it can be quite a bottleneck if everyone arrives at once!"},{"s":377.35,"e":379.41,"t":"OK, I’m happy with that."},{"s":379.84,"e":383.25,"t":"We’re also arranging a New Year’s Eve party."},{"s":383.42,"e":392.66,"t":"We’re expecting that to be a really big event, so instead of the village hall, it’ll be held in the Mountfort Hotel."},{"s":396.87,"e":407.99,"t":"It isn’t in Southoe itself, but it’s only a couple of miles away."},{"s":408.05,"e":412.86,"t":"The hotel will be providing dinner and we’ve booked a band."},{"s":412.99,"e":416.32,"t":"The one thing we haven’t got yet is a poster."},{"s":416.37,"e":420.13,"t":"That isn’t something you could do, by any chance, is it?"},{"s":422.1,"e":427.59,"t":"Before I retired I was a graphic designer, so that’s right up my street."}],"2":[{"s":51.18,"e":57.31,"t":"Good morning, and welcome to Oniton Hall, one of the largest estates in the area."},{"s":57.75,"e":60.84,"t":"My name’s Nick, and I’m one of the guides."},{"s":61.25,"e":68.18,"t":"I’ll give you a brief introduction to the estate while you’re sitting down, and then we’ll walk round."},{"s":68.85,"e":77.85,"t":"The estate consists of the house, gardens, parkland and farm, and it dates back to the fourteenth century."},{"s":78.5,"e":86.91,"t":"The original house was replaced in the late seventeenth century, and of course it has had a large number of owners."},{"s":87.24,"e":98.94,"t":"Almost all of them have left their mark, generally by adding new rooms, like the ballroom and conservatory, or by demolishing others."},{"s":100.07,"e":109.05,"t":"The farm looks much as it’s always done, although the current owner has done a great deal of work to the flower beds."},{"s":109.57,"e":117.39,"t":"In the seventeenth century, the estate was owned by a very wealthy man called Sir Edward Downes."},{"s":117.77,"e":133.21,"t":"His intention was to escape from the world of politics, after years as an active politician, and to build a new house worthy of his big collection of books, paintings and sculptures."},{"s":134.14,"e":145.02,"t":"He broke off contact with his former political allies, and hosted meetings of creative and literary people, like painters and poets."},{"s":145.41,"e":154.48,"t":"Unusually for his time, he didn’t care whether his guests were rich or poor, as long as they had talent."},{"s":155.69,"e":167.65,"t":"Big houses like Oniton had dozens of servants until the 1920s or 30s, and we’ve tried to show what their working lives were like."},{"s":168.49,"e":183.07,"t":"Photographs of course don’t give much of an idea, so instead, as you go round the house, you’ll see volunteers dressed up as nineteenth-century servants, going about their work."},{"s":183.63,"e":191.38,"t":"They’ll explain what they’re doing, and tell you their recipes, or what tools they’re using."},{"s":193.36,"e":198.96,"t":"We’ve just introduced this feature to replace the audio guide we used to have available."},{"s":199.35,"e":203.85,"t":"I see there are a number of children here with you today."},{"s":222.21,"e":229.71,"t":"Our latest addition is child-sized tractors, that you can drive around the grounds."},{"s":284.06,"e":293.94,"t":"Most of the buildings date from the eighteenth century, so you can really step back into an agricultural past."},{"s":295.06,"e":301.94,"t":"Until recently, the dairy was where milk from the cows was turned into cheese."},{"s":302.2,"e":310.76,"t":"It’s now the place to go for lunch, or afternoon tea, or just a cup of coffee and a slice of homemade cake."},{"s":311.67,"e":321.42,"t":"The big stone building that dominates the farm is the large barn, and in here is our collection of agricultural tools."},{"s":321.49,"e":329.23,"t":"These were used in the past to plough the earth, sow seeds, make gates, and much more."},{"s":329.9,"e":338.68,"t":"There’s a small barn, also made of stone, where you can groom the donkeys and horses, to keep their coats clean."},{"s":339.12,"e":344.64,"t":"They really seem to enjoy having it done, and children love grooming them."},{"s":344.9,"e":360.85,"t":"The horses no longer live in the stables, which instead is the place to go to buy gifts, books, our own jams and pickles, and clothes and blankets made of wool from our sheep."},{"s":361.08,"e":372.12,"t":"Outside the shed, which is the only brick building, you can climb into a horse-drawn carriage for a lovely, relaxing tour of the park and farm."},{"s":372.26,"e":376.52,"t":"The carriages are well over a hundred years old."},{"s":377.85,"e":387.6,"t":"And finally, the parkland, which was laid out in the eighteenth century, with a lake and trees that are now well established."},{"s":387.87,"e":393.87,"t":"You’ll see types of cattle and sheep that are hardly ever found on farms these days."},{"s":394.13,"e":399.51,"t":"We’re helping to preserve them, to stop their numbers falling further."}],"3":[{"s":34.65,"e":39.27,"t":"Did you make notes while you were watching the performances of Romeo and Juliet, Gemma?"},{"s":39.31,"e":40.3,"t":"Yes, I did."},{"s":40.34,"e":42.82,"t":"I found it quite hard though."},{"s":42.93,"e":45.51,"t":"I kept getting too involved in the play."},{"s":46.32,"e":48.36,"t":"I ended up not taking notes."},{"s":48.66,"e":51.21,"t":"I wrote down my impressions when I got home."},{"s":51.18,"e":54.07,"t":"Do you mind if I check a few things with you?"},{"s":54,"e":55.47,"t":"In case I’ve missed anything."},{"s":55.83,"e":59.16,"t":"And I’ve also got some questions about our assignment."},{"s":59.26,"e":61.95,"t":"No, it’s good to talk things through."},{"s":62.05,"e":64.11,"t":"I may have missed things too."},{"s":65.02,"e":71.12,"t":"So first of all, I’m not sure how much information we should include in our reviews."},{"s":71.55,"e":75.87,"t":"Well, I don’t think we need to describe what happens."},{"s":75.86,"e":80.74,"t":"Especially as Romeo and Juliet is one of Shakespeare’s most well-known plays."},{"s":80.94,"e":83.22,"t":"Yeah, everyone knows the story."},{"s":83.42,"e":91.38,"t":"In an essay we’d focus on the poetry and Shakespeare’s use of imagery etc., but that isn’t really relevant in a review."},{"s":91.44,"e":96.2,"t":"We’re supposed to focus on how effective this particular production is."},{"s":97.18,"e":100.87,"t":"We should say what made it a success or a failure."},{"s":100.89,"e":105.58,"t":"And part of that means talking about the emotional impact the performance had on us."},{"s":105.48,"e":107.02,"t":"I think that’s important."},{"s":107.97,"e":117.24,"t":"And we should definitely mention how well the director handled important bits of the play – like when Romeo climbs onto Juliet’s balcony."},{"s":117.22,"e":119.51,"t":"And the fight between Mercutio and Tybalt."},{"s":120.84,"e":130.22,"t":"It would also be interesting to mention the theatre space and how the director used it but I don’t think we’ll have space in 800 words."},{"s":131.58,"e":133.56,"t":"That all sounds quite straightforward."},{"s":204.86,"e":210.37,"t":"I thought some things worked really well but there were some problems too."},{"s":210.99,"e":213.19,"t":"What about the set, for example?"},{"s":213.18,"e":216.24,"t":"I think it was visually really stunning."},{"s":216.36,"e":220.4,"t":"I’d say that was probably the most memorable thing about this production."},{"s":221.46,"e":228.17,"t":"The set design was really amazing, but actually I have seen similar ideas used in other productions."},{"s":229.87,"e":235.17,"t":"Some of the scenes were so dimly lit it was quite hard to see."},{"s":235.15,"e":236.96,"t":"I didn’t dislike it."},{"s":237.36,"e":240.28,"t":"It helped to change the mood of the quieter scenes."},{"s":240.27,"e":241.65,"t":"That’s a good point."},{"s":241.67,"e":243.36,"t":"What did you think of the costumes?"},{"s":243.36,"e":247.71,"t":"I was a bit surprised by the contemporary dress, I must say."},{"s":247.81,"e":252.3,"t":"Yeah – I think it worked well, but I had assumed it would be more conventional."},{"s":253.29,"e":264.3,"t":"I liked the music at the beginning and I thought the musicians were brilliant, but I thought they were wasted because the music didn’t have much impact in Acts 2 and 3."},{"s":264.25,"e":265.75,"t":"Yes – that was a shame."},{"s":265.97,"e":270.91,"t":"One problem with this production was that the actors didn’t deliver the lines that well."},{"s":270.99,"e":272.82,"t":"They were speaking too fast."},{"s":272.85,"e":280.19,"t":"It was a problem I agree, but I thought it was because they weren’t speaking loudly enough – especially at key points in the play."},{"s":280.34,"e":282.96,"t":"I actually didn’t have a problem with that."},{"s":283.46,"e":288.68,"t":"It’s been an interesting experience watching different versions of Romeo and Juliet, hasn’t it?"},{"s":289.13,"e":292.77,"t":"It’s made me realise how relevant the play still is."},{"s":293.58,"e":298.17,"t":"I mean a lot’s changed since Shakespeare’s time, but in many ways nothing’s changed."},{"s":298.11,"e":302.95,"t":"There are always disagreements and tension between teenagers and their parents."},{"s":303.1,"e":311.05,"t":"Yes, that’s something all young people can relate to – more than the violence and the extreme emotions in the play."},{"s":311.13,"e":313.8,"t":"How did you find watching it in translation?"},{"s":315.66,"e":320.58,"t":"I expected to find it more challenging, but I could follow the story pretty well."},{"s":320.76,"e":326.34,"t":"I stopped worrying about not being able to understand all the words and focused on the actors’ expressions."},{"s":326.85,"e":328.53,"t":"The ending was pretty powerful."},{"s":329.42,"e":332.7,"t":"That somehow intensified the emotion for me."},{"s":332.73,"e":337.88,"t":"Did you know Shakespeare’s been translated into more languages than any other writer?"},{"s":337.84,"e":342.82,"t":"What’s the reason for his international appeal, do you think?"},{"s":343.03,"e":349.06,"t":"I was reading that it’s because his plays are about basic themes that people everywhere are familiar with."},{"s":349.04,"e":353.38,"t":"Yeah, and they can also be understood on different levels."},{"s":353.32,"e":355.52,"t":"The characters have such depth."},{"s":355.73,"e":360.0,"t":"Right – which allows directors to experiment and find new angles."}],"4":[{"s":96.41,"e":110.53,"t":"In order to illustrate its effect, I’m going to focus on the Icelandic language, which is spoken by around 321,000 people, most of whom live in Iceland – an island in the North Atlantic Ocean."},{"s":110.58,"e":116.74,"t":"The problem for this language is not the number of speakers – even though this number is small."},{"s":116.86,"e":121.13,"t":"Nor is it about losing words to other languages, such as English."},{"s":121.67,"e":133.47,"t":"In fact, the vocabulary of Icelandic is continually increasing because when speakers need a new word for something, they tend to create one, rather than borrowing from another language."},{"s":133.57,"e":146.6,"t":"All this makes Icelandic quite a special language – it’s changed very little in the past millennium, yet it can handle twenty-first-century concepts related to the use of computers and digital technology."},{"s":146.76,"e":155.61,"t":"Take, for example, the word for web browser … this is vafri in Icelandic, which comes from the verb ‘to wander’."},{"s":155.88,"e":161.55,"t":"I can’t think of a more appropriate term because that’s exactly what you do mentally when you browse the internet."},{"s":162.06,"e":166.8,"t":"Then there’s an Icelandic word for podcast – which is too hard to pronounce!"},{"s":166.82,"e":167.87,"t":"And so on."},{"s":168.06,"e":179.54,"t":"Icelandic, then, is alive and growing, but – and it’s a big but – young Icelanders spend a great deal of time in the digital world and this world is predominantly English."},{"s":180.18,"e":181.98,"t":"Think about smartphones."},{"s":182.49,"e":194.38,"t":"They didn’t even exist until comparatively recently, but today young people use them all the time to read books, watch TV or films, play games, listen to music, and so on."},{"s":195.13,"e":208.03,"t":"Obviously, this is a good thing in many respects because it promotes their bilingual skills, but the extent of the influence of English in the virtual world is staggering and it’s all happening really fast."},{"s":208.17,"e":215.74,"t":"For their parents and grandparents, the change is less concerning because they already have their native-speaker skills in Icelandic."},{"s":215.87,"e":220.47,"t":"But for young speakers – well, the outcome is a little troubling."},{"s":238.66,"e":247.2,"t":"The very real and worrying consequence of all this is that the young generation in Iceland is at risk of losing its mother tongue."},{"s":271.07,"e":277.41,"t":"The other drawback of Icelandic is the grammar, which is significantly more complex than in most languages."},{"s":277.49,"e":282.79,"t":"At the moment, the tech giants are simply not interested in tackling this."},{"s":283.37,"e":287.39,"t":"So, what is the Icelandic government doing about this?"},{"s":303.06,"e":309.27,"t":"On the positive side, they know that Icelandic is still the official language of education and government."},{"s":309.35,"e":318.95,"t":"It has survived for well over a thousand years and the experts predict that its future in this nation state is sound and will continue to be so."},{"s":319.09,"e":326.13,"t":"However, there’s no doubt that it’s becoming an inevitable second choice in young people’s lives."},{"s":326.31,"e":328.75,"t":"This raises important questions."},{"s":329.19,"e":336.84,"t":"When you consider how much of the past is tied up in a language, will young Icelanders lose their sense of their own identity?"},{"s":336.96,"e":340.58,"t":"Another issue that concerns the government of Iceland is this."},{"s":340.76,"e":350.07,"t":"If children are learning two languages through different routes, neither of which they are fully fluent in, will they be able to express themselves properly?"}]},"3":{"1":[{"s":87.83,"e":98.7,"t":"Jack, I’m thinking of taking the kids to the seaside on a surfing holiday this summer and I wanted to ask your advice – as I know you’re such an expert."},{"s":98.76,"e":104.54,"t":"Well, I don’t know about that, but yes, I’ve done a bit of surfing over the years."},{"s":106.41,"e":110.52,"t":"I think it’s the kind of holiday all the family can enjoy together."},{"s":111.29,"e":116.06,"t":"The thing about surfing is that it’s great for all ages and all abilities."},{"s":116.25,"e":119.01,"t":"My youngest started when he was only three!"},{"s":120.4,"e":124.1,"t":"But it’s quite physically demanding, isn’t it?"},{"s":124.16,"e":126.62,"t":"I’ve heard you need to be pretty fit."},{"s":127.1,"e":131.27,"t":"You’ll certainly learn more quickly and won’t tire as easily."},{"s":131.44,"e":134.17,"t":"Well – that should be OK for us."},{"s":134.21,"e":138.03,"t":"You’ve been surfing a few times in Ireland, haven’t you?"},{"s":138.85,"e":143.03,"t":"There’s some great surfing there, which people don’t always realise."},{"s":143.28,"e":148.62,"t":"And which locations would you recommend? – there seem to be quite a few."},{"s":148.67,"e":150.02,"t":"Yes, there are loads."},{"s":150.07,"e":152.36,"t":"Last year we went to County Donegal."},{"s":152.43,"e":155.99,"t":"There are several great places to surf there."},{"s":156.24,"e":158.76,"t":"What about in County Clare?"},{"s":159.02,"e":161.9,"t":"I read that’s also really good for surfing."},{"s":162.99,"e":165.38,"t":"I’ve been there a few times."},{"s":165.42,"e":167.27,"t":"Most people go to Lahinch."},{"s":167.57,"e":169.05,"t":"My kids love it there."},{"s":169.04,"e":172.69,"t":"The waves aren’t too challenging and the town is very lively."},{"s":172.87,"e":175.1,"t":"Are there good hotels there?"},{"s":175.28,"e":181.68,"t":"Yes – some very nice ones and there are also a few basic hostels and campsites."},{"s":182.05,"e":186.03,"t":"It’s great if you need lessons as the surf schools are excellent."},{"s":204.87,"e":207.51,"t":"That was a few years ago when the kids were younger."},{"s":223.11,"e":230.3,"t":"I put the kids into the surf camp they run during the summer for 10–16 year olds."},{"s":231.48,"e":233.52,"t":"How long was that for?"},{"s":233.54,"e":236.17,"t":"Three hours every day for a week."},{"s":236.21,"e":239.9,"t":"It was perfect – they were so tired out after that."},{"s":240.08,"e":241.42,"t":"I can imagine."},{"s":241.73,"e":249.09,"t":"One thing we did while the kids were surfing was to rent some kayaks to have a look around the bay which is nearby."},{"s":249.12,"e":250.78,"t":"It’s really beautiful."},{"s":289.1,"e":294.19,"t":"Now the only time I went to Ireland it rained practically every day."},{"s":294.32,"e":298.86,"t":"Mmm yes – that can be a problem – but you can surf in the rain, you know."},{"s":299.05,"e":302.25,"t":"It doesn’t have the same appeal, somehow."},{"s":302.37,"e":311.84,"t":"Well, the weather’s been fine the last couple of years when I’ve been there, but actually, it tends to rain more in August than in the spring or autumn."},{"s":312.03,"e":316.13,"t":"September’s my favourite month because the water is warmer then."},{"s":316.25,"e":320.15,"t":"The only problem is that the kids are back to school then."},{"s":321.0,"e":325.74,"t":"But one good thing about Irish summers is that it doesn’t get too hot."},{"s":326.08,"e":333.23,"t":"The average temperature is about 19 degrees and it usually doesn’t go above 25 degrees."},{"s":333.51,"e":334.97,"t":"That sounds alright."},{"s":335.26,"e":337.3,"t":"Now what about costs?"},{"s":337.58,"e":343.47,"t":"Surfing is a pretty cheap holiday really – the only cost is the hire of equipment."},{"s":343.55,"e":355.24,"t":"You can expect to pay a daily rate of about 30 euros for the hire of a wetsuit and board – but you can save about 40 euros if you hire by the week."},{"s":357.52,"e":363.51,"t":"It’s important to make sure you get good quality wetsuits – you’ll all get too cold if you don’t."},{"s":363.78,"e":366.56,"t":"And make sure you also get boots."},{"s":367.05,"e":371.66,"t":"They keep your feet warm and it’s easier to surf with them on too."}],"2":[{"s":96.54,"e":100.89,"t":"I know that many parents who work find this service invaluable."},{"s":101.27,"e":107.63,"t":"You can leave your child with us safe in the knowledge that they will be extremely well cared for."},{"s":107.79,"e":116.36,"t":"We are insured to provide care for up to 70 children, although we rarely have this many attending at any one session."},{"s":117.12,"e":126.6,"t":"I think we generally expect around 50–60 children for the afternoon sessions and about half that number for the breakfast sessions."},{"s":127.15,"e":134.2,"t":"Although we currently do have 70 children registered with us, not all of these attend every day."},{"s":134.35,"e":141.73,"t":"It’s ten years since we began offering an extended hours service and we’ve come a long way during that time."},{"s":142.11,"e":147,"t":"When we first opened, we only had about 20 children attending regularly."},{"s":147.89,"e":154.35,"t":"We try to keep our costs as low as we can and we think we provide very good value for money."},{"s":154.41,"e":160.71,"t":"For the afternoon sessions, which run from 3.30 until 6 p.m., it’s £7.20."},{"s":170.57,"e":175.74,"t":"The cost of the childcare includes food and snacks."},{"s":175.98,"e":183.06,"t":"They’ll be given breakfast in the morning and in the afternoon, a healthy snack as soon as they finish school."},{"s":183.21,"e":190.12,"t":"At 5 p.m. children are given something more substantial, such as pasta or a casserole."},{"s":190.29,"e":198.1,"t":"Please inform us of any allergies that your child might have and we’ll make sure they’re offered a suitable alternative."},{"s":206.02,"e":215.18,"t":"We offer a really varied and exciting programme to keep the children entertained – we don’t want them to feel as if they are still at school!"},{"s":291.55,"e":302.48,"t":"As well as being able to use the playground equipment, computers and the library, there is usually at least one ‘special’ activity that children can do each day."},{"s":303.15,"e":304.88,"t":"For example, Spanish."},{"s":305.13,"e":312.9,"t":"We have a specialist teacher coming in every Thursday to give a basic introduction to the language through games and songs."},{"s":313.23,"e":318.54,"t":"She does two sessions: one for the over 8s and one for the younger children."},{"s":318.58,"e":325.99,"t":"This is the only activity which we have to make an extra charge for – but it’s well worth it."},{"s":326.25,"e":330.09,"t":"Once a week the children have the opportunity to do some music."},{"s":330.13,"e":335.27,"t":"We’re very lucky that one of our staff is a member of a folk band."},{"s":335.32,"e":339.68,"t":"On Mondays, she teaches singing and percussion to groups of children."},{"s":340.25,"e":350.74,"t":"We do rely on parental support for this, so if any of you sing or play an instrument and would be prepared to help out at these sessions, we’d be delighted."},{"s":351.75,"e":355.68,"t":"Painting continues to be one of the most popular activities."},{"s":355.95,"e":367.27,"t":"To begin with we weren’t keen on offering this because of the extra mess involved, but children kept asking if they could do some art and so we finally gave in."},{"s":367.32,"e":373.47,"t":"Art is great for helping the children to relax after working hard at school all day."},{"s":373.64,"e":382.59,"t":"Yoga is something that we’ve been meaning to introduce for some time but haven’t been able to find anyone available to teach it – until now that is."},{"s":382.66,"e":385.16,"t":"So we’ll see how this goes."},{"s":385.43,"e":389.9,"t":"Hopefully, children will benefit in all sorts of ways from this."},{"s":390.39,"e":393.06,"t":"Cooking is another popular activity."},{"s":393.41,"e":397.62,"t":"They make a different sort of cake, or pizza or bread each week."}],"3":[{"s":53.75,"e":58.25,"t":"Hello Dr Green – I’m here to talk to you about my work placement."},{"s":58.3,"e":60.87,"t":"Oh yes, it’s Holly, isn’t it?"},{"s":61.41,"e":64.2,"t":"So, which work placement have you chosen?"},{"s":64.37,"e":68.32,"t":"I decided to go for the Orion Stadium placement."},{"s":68.44,"e":75.23,"t":"The event I’ll be managing is one where I’m helping to set up a sports competition for primary school children."},{"s":75.81,"e":81.43,"t":"That’s always a popular placement – even though it can be tougher than you think working with children."},{"s":81.46,"e":90.45,"t":"I know, but it’s the fresh air that attracts me – organising something indoors doesn’t have the same appeal, even though it might be fun."},{"s":90.85,"e":96.53,"t":"OK, so obviously safety’s going to be one of your key concerns for this event."},{"s":96.62,"e":99.34,"t":"Yes, I’ve already thought about that."},{"s":99.35,"e":102.87,"t":"I’ll need to make sure none of the equipment’s damaged."},{"s":102.99,"e":108.12,"t":"Ah well, you’ll be working with schools, so the equipment will be their responsibility."},{"s":108.57,"e":112.76,"t":"However, the grounds and what goes on there will be yours."},{"s":112.94,"e":120.13,"t":"Oh I see – that’ll include keeping everyone within the boundary once they’re in their kit and on the field?"},{"s":120.23,"e":130.73,"t":"Exactly – you’ll need to inspect areas like changing rooms as well for anything someone can trip over, but your main priority will be not to lose anyone!"},{"s":131.39,"e":134.61,"t":"I’ll need staff to help with that."},{"s":134.85,"e":137.25,"t":"And don’t forget about the spectators."},{"s":137.75,"e":142.8,"t":"I was thinking that many of them will be parents, who could help run the event."},{"s":142.84,"e":144.49,"t":"I wouldn’t rely on that."},{"s":144.53,"e":148.16,"t":"They’ll be more interested in filming their children than volunteering."},{"s":148.51,"e":152.19,"t":"I’ll need to make sure they don’t interfere with events doing that!"},{"s":152.3,"e":160.61,"t":"And that’s not always easy, especially when a proud parent’s trying to get a snap of their child and you want them to move elsewhere."},{"s":161.81,"e":164.37,"t":"What about the scheduling?"},{"s":164.82,"e":174.92,"t":"With sporting events there are all sorts of things that can alter the timetable – like rain, for instance – though so far, we’ve always been lucky with that."},{"s":175.28,"e":180.59,"t":"Yeah, and I was thinking about what to do if someone got hurt as well."},{"s":180.77,"e":184.05,"t":"I know that last year that caused a terrible delay."},{"s":184.17,"e":186.66,"t":"You have to be prepared for such things."},{"s":187.36,"e":193.63,"t":"What if a match ends in a draw – do you let the teams keep going until someone wins?"},{"s":193.72,"e":198.1,"t":"That’ll be up to you – and again, you need to plan for it."},{"s":254.67,"e":257.49,"t":"So, let’s talk about those a bit."},{"s":257.5,"e":261.07,"t":"Well, I think my communication skills are pretty good."},{"s":261.25,"e":266.37,"t":"I can talk on the phone to people and book venues and that kind of thing."},{"s":266.51,"e":270.49,"t":"Good – just remember it isn’t only about what you say."},{"s":270.75,"e":275.84,"t":"If you meet someone face-to-face and want to persuade them to be a sponsor, for example …"},{"s":275.98,"e":278.27,"t":"Oh, I’ll dress up for that!"},{"s":279.17,"e":282.88,"t":"Let’s go on to think about your organisational skills."},{"s":283.12,"e":289.47,"t":"You’re working in a very people-based industry and that means things won’t always go to plan."},{"s":289.71,"e":293.22,"t":"I guess it’s being prepared to make changes that matters."},{"s":294.63,"e":300.38,"t":"You may have to make an on-the-spot change to a timetable because of a problem you hadn’t anticipated …"},{"s":302.91,"e":305.4,"t":"How’s your time management these days?"},{"s":316.09,"e":320.02,"t":"I know I’ve got to look calm even if I’m in a panic."},{"s":320.01,"e":324.05,"t":"Just think to yourself – no one must know I’m under pressure."},{"s":324.11,"e":327.09,"t":"Yeah – even though I’m multi-tasking like crazy!"},{"s":328.02,"e":331.74,"t":"Another skill that events managers need is creativity."},{"s":332.15,"e":341.68,"t":"Often your client has what we call the ‘big picture’ idea, but it’s up to the events manager to think of all the fine points that go to making it work."},{"s":341.83,"e":347.86,"t":"Right, so I need to listen carefully to that idea and then fill in all the gaps."},{"s":349.04,"e":354.56,"t":"And you’ll have a team working under you, so another key skill is leadership."},{"s":354.96,"e":360.68,"t":"Your team may have lots of ideas too, but you’ve got to make the ultimate choices."},{"s":360.76,"e":364.82,"t":"Do we have refreshments inside or out, for example?"},{"s":364.83,"e":367.69,"t":"Isn’t it better to be democratic?"},{"s":367.95,"e":371.94,"t":"It’s a nice idea, but you have the ultimate responsibility."},{"s":372.11,"e":375.27,"t":"So, believe in what you think best."},{"s":375.54,"e":380.82,"t":"Be prepared to say ‘yes’, that’s a good idea but it won’t work here."},{"s":380.83,"e":382.59,"t":"I see what you mean."},{"s":382.77,"e":385.95,"t":"What about the networking side of things?"},{"s":386.13,"e":393.26,"t":"I know it’s an area that a lot of students worry about because we don’t have much experience to offer others."},{"s":393.38,"e":398.77,"t":"But even without it – you can still be an interesting person with useful ideas."},{"s":399.05,"e":401.96,"t":"And the more people you impress, the better."},{"s":402.06,"e":405.42,"t":"I guess that will help me when I apply for a real job."},{"s":405.51,"e":411.49,"t":"Exactly – think ahead – remember what your ambitions are and keep them in mind."}],"4":[{"s":77.68,"e":88.08,"t":"Some travel seasonally for relatively short distances, such as birds that move from their winter habitats in lowlands to mountain tops for the summers."},{"s":88.33,"e":98.86,"t":"Others, like the Arctic Tern, travel more than 25,000 miles seasonally between the northern and southern poles."},{"s":99.54,"e":105.27,"t":"Bird migration has been studied over many centuries through a variety of observations."},{"s":105.62,"e":112.75,"t":"But until relatively recently, where birds went to in the winter was considered something of a mystery."},{"s":113.16,"e":122.97,"t":"The lack of modern science and technology led to many theories that we now recognize as error-filled and even somewhat amusing."},{"s":123.72,"e":137.68,"t":"Take hibernation theory for example – two thousand years ago, it was commonly believed that when birds left an area, they went underwater to hibernate in the seas and oceans."},{"s":137.89,"e":150.25,"t":"Another theory for the regular appearance and disappearance of birds was that they spent winter hidden in mud till the weather changed and food became abundant again."},{"s":150.51,"e":162.93,"t":"The theory that some birds hibernate persisted until experiments were done on caged birds in the 1940s which demonstrated that birds have no hibernation instinct."},{"s":163.18,"e":179.34,"t":"One of the earliest naturalists and philosophers from ancient Greece was Aristotle who was the first writer to discuss the disappearance and reappearance of some bird species at certain times of year."},{"s":179.51,"e":188.79,"t":"He developed the theory of transmutation, the seasonal change of one species into another, by observing redstarts and robins."},{"s":205.16,"e":218.13,"t":"These assumptions are understandable given that this pair of species are similar in shape, but are a classic example of an incorrect interpretation based on correct observations."},{"s":218.38,"e":227.88,"t":"The most bizarre theory was put forward by an English amateur scientist, Charles Morton, in the seventeenth century."},{"s":228.06,"e":236.28,"t":"He wrote a surprisingly well-regarded paper claiming that birds migrate to the moon and back every year."},{"s":236.88,"e":243.96,"t":"He came to this conclusion as the only logical explanation for the total disappearance of some species."},{"s":244.62,"e":258.99,"t":"One of the key moments in the development of migration theory came in 1822 when a white stork was shot in Germany."},{"s":259.23,"e":273.87,"t":"This particular stork made history because of the long spear in its neck which incredibly had not killed it – everyone immediately realised this spear was definitely not European."},{"s":274.01,"e":278.6,"t":"It turned out to be a spear from a tribe in Central Africa."},{"s":278.94,"e":290.27,"t":"This was a truly defining moment in the history of ornithology because it was the first evidence that storks spend their winters in sub-Saharan Africa."},{"s":291.55,"e":300.37,"t":"You can still see the ‘arrow stork’ in the Zoological Collection of the University of Rostock in Germany."},{"s":300.97,"e":315.27,"t":"People gradually became aware that European birds moved south in autumn and north in summer but didn’t know much about it until the practice of catching birds and putting rings on their legs became established."},{"s":315.86,"e":325.39,"t":"Before this, very little information was available about the actual destinations of particular species and how they travelled there."},{"s":325.73,"e":334.78,"t":"People speculated that larger birds provided a kind of taxi service for smaller birds by carrying them on their backs."},{"s":334.94,"e":344.15,"t":"This idea came about because it seemed impossible that small birds weighing only a few grams could fly over vast oceans."},{"s":344.44,"e":354.66,"t":"This idea was supported by observations of bird behaviour such as the harassment of larger birds by smaller birds."},{"s":355.16,"e":364.62,"t":"The development of bird ringing, by a Danish schoolteacher, Hans Christian Cornelius Mortensen, made many discoveries possible."},{"s":364.85,"e":378.11,"t":"This is still common practice today and relies upon what is known as ‘recovery’ – this is when ringed birds are found dead in the place they have migrated to, and identified."},{"s":378.81,"e":390.35,"t":"Huge amounts of data were gathered in the early part of the twentieth century and for the first time in history people understood where birds actually went to in winter."},{"s":390.54,"e":399.04,"t":"In 1931, an atlas was published showing where the most common species of European birds migrated to."}]},"4":{"1":[{"s":81.56,"e":84.82,"t":"Hello, Easy Life Cleaning Services, Jacinta speaking."},{"s":86.0,"e":91.32,"t":"I’m looking for a cleaning service for my apartment – do you do domestic cleaning?"},{"s":94.26,"e":97.5,"t":"Do you have a basic cleaning package?"},{"s":98.27,"e":103.57,"t":"For a one-bedroom flat we’re probably looking at about two hours for a clean."},{"s":103.55,"e":109.15,"t":"So we’d do a thorough clean of all surfaces in each room, and polish them where necessary."},{"s":109.37,"e":111.39,"t":"Does your apartment have carpets?"},{"s":111.6,"e":115.26,"t":"No, I don’t have any, but the floor would need cleaning."},{"s":117.63,"e":121.39,"t":"And we’d do a thorough clean of the kitchen and bathroom."},{"s":121.82,"e":130.67,"t":"Then we have some additional services which you can request if you want – so for example, we can clean your oven for you every week."},{"s":130.72,"e":135.49,"t":"Actually, I hardly ever use that, but can you do the fridge?"},{"s":136.05,"e":138.64,"t":"Would you like that done every week?"},{"s":139.64,"e":143.8,"t":"And would ironing clothes be an additional service you can do?"},{"s":143.84,"e":144.81,"t":"Yes, of course."},{"s":144.84,"e":148.49,"t":"It wouldn’t be much, just my shirts for work that week."},{"s":149.85,"e":152.91,"t":"And we could also clean your microwave if you want."},{"s":152.93,"e":156.93,"t":"No, I wipe that out pretty regularly so there’s no need for that."},{"s":157.28,"e":163.3,"t":"We also offer additional services that you might want a bit less often, say every month."},{"s":163.35,"e":168.16,"t":"So for example, if the inside of your windows need cleaning, we could do that."},{"s":168.22,"e":169.61,"t":"Yes, that’d be good."},{"s":169.67,"e":177.57,"t":"I’m on the fifteenth floor, so the outside gets done regularly by specialists, but the inside does get a bit grubby."},{"s":177.63,"e":181.59,"t":"And we could arrange for your curtains to get cleaned if necessary."},{"s":182.61,"e":185.94,"t":"But would you be able to do something about the balcony?"},{"s":185.94,"e":191.82,"t":"It’s quite small and I don’t use it much, but it could do with a wash every month or so."},{"s":191.79,"e":194.49,"t":"Yes, we can get the pressure washer onto that."},{"s":241.41,"e":250.87,"t":"For example, if you have a problem with water and you need a plumber in a hurry, we can put you in touch with a reliable one who can come out straightaway."},{"s":250.98,"e":253.67,"t":"And the same thing if you need an electrician."},{"s":254.47,"e":255.36,"t":"That’s good to know."},{"s":255.43,"e":260.66,"t":"I’ve only just moved here so I don’t have any of those sorts of contacts."},{"s":274.33,"e":278.2,"t":"So if you’re troubled by allergies, this can make a big difference."},{"s":278.91,"e":282.75,"t":"In fact, I don’t have that sort of problem, but I’ll bear it in mind."},{"s":282.99,"e":286.32,"t":"Now can you tell me a bit about your cleaning staff?"},{"s":287.19,"e":290.96,"t":"So all our cleaners are very carefully selected."},{"s":302.4,"e":306.78,"t":"Then if we think they might be suitable for the job, we give them training for it."},{"s":306.96,"e":312.08,"t":"That lasts for two weeks so it’s very thorough, and at the end of it, they have a test."},{"s":323.8,"e":327.36,"t":"So we can pick up any problems straightaway and deal with them."},{"s":327.6,"e":330.05,"t":"OK, well that all sounds good."},{"s":330.3,"e":333.28,"t":"And will I always have the same cleaner?"},{"s":333.29,"e":338.36,"t":"Yes, we do our best to organise it that way, and we usually manage it."}],"2":[{"s":53.13,"e":65.15,"t":"As many of you here today have worked in the hotel industry for some time, I’m sure you have experienced the problem of high staff turnover in your hotels."},{"s":65.88,"e":74.64,"t":"Every hotel relies on having loyal and experienced members of staff who make sure that everything runs smoothly."},{"s":74.85,"e":80.86,"t":"If staff are constantly changing, it can make life difficult for everyone."},{"s":81.93,"e":86.52,"t":"But why do staff leave frequently in many hotels?"},{"s":111.48,"e":116.12,"t":"So, what kind of problems does a high turnover of staff cause?"},{"s":116.63,"e":128.99,"t":"Well, having to recruit new staff all the time can be very time-consuming, and managers may have to cover some duties while waiting for new staff to arrive."},{"s":129.24,"e":136.32,"t":"This means they don’t have time to think about less immediate problems such as how to improve their service."},{"s":136.92,"e":143.13,"t":"When staff leave, it can also severely affect the colleagues they leave behind."},{"s":143.64,"e":150.51,"t":"It has a negative effect on remaining staff, who may start to feel that they too should be thinking about leaving."},{"s":151.35,"e":155.01,"t":"So, what can be done to change this situation?"},{"s":155.52,"e":163.18,"t":"Firstly, managers should stop making basic errors which leave their staff feeling upset and resentful."},{"s":163.86,"e":170.9,"t":"When organising shifts, for example, make sure you never give certain staff preferential treatment."},{"s":171.25,"e":180.29,"t":"All staff should be given some choice about when they work, and everyone should have to work some evening and weekend shifts."},{"s":181.08,"e":188.07,"t":"If you treat staff fairly, they’ll be more likely to step in and help when extra staff are needed."},{"s":189.72,"e":194.55,"t":"Keeping staff happy has other tangible benefits for the business."},{"s":195.03,"e":197.77,"t":"Take the Dunwich Hotel as an example."},{"s":198.0,"e":209.6,"t":"It had been experiencing a problem with staff complaints and in order to deal with this, invested in staff training and improved staff conditions."},{"s":210.01,"e":220.52,"t":"Not only did the level of complaints fall, but they also noticed a significant increase in the amount each customer spent during their stay."},{"s":220.74,"e":225.78,"t":"They have now introduced a customer loyalty scheme which is going really well."},{"s":272.94,"e":284.2,"t":"Now I’d like to look at some ways you can reduce staff turnover in your hotels, and I’ll do this by giving some examples of hotels where I’ve done some training recently."},{"s":285.26,"e":292.12,"t":"The Sun Club received feedback which showed that staff thought managers didn’t value their opinions."},{"s":292.63,"e":299.54,"t":"They weren’t made to feel they were partners who were contributing to the success of the business as a whole."},{"s":299.71,"e":301.69,"t":"This situation has changed."},{"s":302.01,"e":309.25,"t":"Junior staff at all levels are regularly invited to meetings where their ideas are welcomed."},{"s":310.5,"e":315.99,"t":"A year ago, The Portland recognised the need to invest in staff retention."},{"s":316.3,"e":322.9,"t":"Their first step was to introduce a scheme for recognising talent amongst their employees."},{"s":323.03,"e":331.71,"t":"The hope is that organising training for individuals with management potential will encourage them to stay with the business."},{"s":332.41,"e":342.02,"t":"At Bluewater, managers decided to recognise 50 high achievers from across the company’s huge hotel chain."},{"s":348.31,"e":356.29,"t":"Fun is an important element in the trips, but there’s also the opportunity to learn something useful."},{"s":357.02,"e":365.27,"t":"This year’s trip included a visit to a brewery, where staff learned about the new beer that would be served in the hotel."},{"s":365.95,"e":372.78,"t":"Pentlow Hotels identified that retention of junior reception staff was an issue."},{"s":372.84,"e":383.37,"t":"In order to encourage them to see that working in a hotel could be worthwhile and rewarding, with good prospects, they introduced a management programme."},{"s":383.54,"e":390.69,"t":"These staff were given additional responsibilities and the chance to work in various roles in the hotel."},{"s":392.03,"e":396.25,"t":"Green Planet wanted to be seen as a caring employer."},{"s":396.69,"e":407.4,"t":"To make life easier for staff, many of whom had childcare responsibilities, the hotel began issuing vouchers to help cover the cost of childcare."},{"s":408.04,"e":414.86,"t":"Louise Marsh at The Amesbury has one of the best staff retention rates in the business."},{"s":415.17,"e":423.63,"t":"Since she joined the company, she has made a huge effort to achieve this by creating a co-operative and supportive environment."},{"s":423.96,"e":429.09,"t":"For her, the staff are part of a large family where everyone is valued."}],"3":[{"s":41.83,"e":45.4,"t":"Hi Thomas, how are you enjoying the course so far?"},{"s":45.39,"e":47.04,"t":"Yeah, I think it’s good."},{"s":47.35,"e":50.87,"t":"Remind me – why did you decide to study sports science?"},{"s":50.98,"e":54.44,"t":"Didn’t you want to be a professional athlete when you were at school?"},{"s":54.39,"e":60.42,"t":"Yeah – that was my goal, and all my classmates assumed I would achieve it; they thought I was brilliant."},{"s":60.31,"e":62.06,"t":"That must have been a nice feeling."},{"s":62.0,"e":64.31,"t":"Mm, I thought I could win anything."},{"s":64.44,"e":68.57,"t":"There was no one who could run faster than me."},{"s":70.92,"e":73.73,"t":"Did your mum and dad want you to be more ‘academic’?"},{"s":73.92,"e":75.19,"t":"Not at all."},{"s":75.38,"e":77.93,"t":"Perhaps they should have pushed me harder, though."},{"s":77.9,"e":79.2,"t":"What do you mean?"},{"s":79.24,"e":81.59,"t":"I think I should have practised more."},{"s":81.63,"e":83.21,"t":"What makes you say that?"},{"s":87.4,"e":89.51,"t":"I didn’t know that."},{"s":89.55,"e":95.7,"t":"I was chosen to go there out of loads of kids and run with some of the top teenage athletes in the world."},{"s":96.15,"e":100.08,"t":"And … I was so calm about it."},{"s":100.41,"e":102.93,"t":"I just kept thinking how fortunate I was."},{"s":102.97,"e":104.99,"t":"What a great chance this was!"},{"s":105.06,"e":107.54,"t":"Everyone back home was so proud of me."},{"s":108.18,"e":112.68,"t":"But once we started competing, I very quickly realised I wasn’t good enough."},{"s":113.43,"e":115.58,"t":"That must have been a huge shock."},{"s":115.62,"e":117.77,"t":"I thought ‘this can’t be happening’!"},{"s":117.81,"e":119.49,"t":"I was used to winning."},{"s":119.53,"e":121.17,"t":"I’m sorry to hear that."},{"s":130.61,"e":132.1,"t":"It’s going to be good."},{"s":132.04,"e":135.27,"t":"Oh, I agree – I chose it because of that."},{"s":189.52,"e":192.99,"t":"We have to cover more than one sport, don’t we?"},{"s":193.48,"e":201.67,"t":"You know – we always think technology is about the future, but we could gather some ideas about past developments in sport."},{"s":201.79,"e":205.02,"t":"Look at early types of equipment perhaps?"},{"s":205.6,"e":212.82,"t":"Uh, I remember reading something about table tennis bats once – how they ended up being covered with pimpled rubber."},{"s":212.85,"e":216.1,"t":"Cos they were just wooden at first, I’d imagine."},{"s":216.73,"e":224.11,"t":"In about the 1920s, a factory was making rolls of the rubber in bulk for something like horse harnesses."},{"s":225.17,"e":230.35,"t":"Yeah – and someone realised that it’d make a perfect covering for the wooden bats."},{"s":230.44,"e":235.18,"t":"So what about cricket – that’s had a few innovative changes."},{"s":235.22,"e":237.89,"t":"Maybe the pads they wear on their legs?"},{"s":255.64,"e":259.83,"t":"Wow, players have to protect themselves from getting hurt!"},{"s":260.1,"e":262.78,"t":"I mean everyone wears one now."},{"s":262.93,"e":265.33,"t":"Mm, unlike the cycle helmet."},{"s":265.21,"e":272.58,"t":"Well, unless you’re a professional, but you’re right, many ordinary bikers don’t wear a helmet."},{"s":272.76,"e":276.28,"t":"Hey, look at these pictures of original helmet designs."},{"s":276.56,"e":279.06,"t":"This one looks like an upside-down bowl!"},{"s":279.37,"e":284.65,"t":"Yet, the woman’s laughing – she’s so proud to be wearing it!"},{"s":284.69,"e":290.14,"t":"It says serious cyclists ended up with wet hair from all the hard exercise."},{"s":290.1,"e":296.22,"t":"I guess that’s why they have large air vents in them now so that the skin can breathe more easily."},{"s":296.55,"e":299.36,"t":"OK, so we’ve done helmets."},{"s":299.67,"e":305.62,"t":"What about golf balls or better still golf clubs – they’ve changed a lot."},{"s":305.54,"e":315.53,"t":"Yeah – I remember my great grandfather telling me that because a club was made entirely of wood, it would easily break and players had to get another."},{"s":315.53,"e":318.53,"t":"There’s no wood at all in them now, is there?"},{"s":318.53,"e":320.63,"t":"No – they’re much more powerful."},{"s":320.82,"e":323.22,"t":"The same must be true of hockey sticks."},{"s":323.4,"e":328.75,"t":"I don’t think so because players still use wooden sticks today."},{"s":328.99,"e":336.18,"t":"What it does say here, though, is that when the game started you had to produce a stick yourself."},{"s":336.24,"e":339.25,"t":"I guess they just weren’t being manufactured."},{"s":340.15,"e":342.74,"t":"So, one more perhaps."},{"s":342.88,"e":344.05,"t":"What about football?"},{"s":344.19,"e":348.28,"t":"Well, I know the first balls were made of animal skin."},{"s":348.31,"e":356.55,"t":"Yeah, they covered them with pieces of leather that were stitched together, but … the balls let in water when it rained."},{"s":356.59,"e":359.29,"t":"Oh, that would have made them much heavier."},{"s":360.8,"e":364.31,"t":"You can imagine the damage to players’ necks when the ball was headed."},{"s":364.39,"e":367.24,"t":"How painful that must have been!"}],"4":[{"s":72.62,"e":79.05,"t":"Today we’re going to look at another natural food product and that’s maple syrup."},{"s":79.57,"e":81.36,"t":"What is this exactly?"},{"s":114.36,"e":122.61,"t":"It contains no preservatives or added ingredients, and it provides a healthy alternative to refined sugar."},{"s":122.69,"e":129.86,"t":"Let’s just talk a bit about the maple tree itself, which is where maple syrup comes from."},{"s":130.45,"e":140.76,"t":"So, there are many species of maple tree, and they’ll grow without fertilizer in areas where there’s plenty of moisture in the soil."},{"s":157.34,"e":172.35,"t":"There are only certain parts of the world that provide all these conditions: one is Canada, and by that, I mean all parts of Canada, and the other is the north-eastern states of North America."},{"s":172.64,"e":177.92,"t":"In these areas, the climate suits the trees perfectly."},{"s":178.19,"e":191.95,"t":"In fact, Canada produces over two-thirds of the world’s maple syrup, which is why the five-pointed maple leaf is a Canadian symbol and has featured on the flag since 1964."},{"s":192.89,"e":196.49,"t":"So how did maple syrup production begin?"},{"s":197.1,"e":206.04,"t":"Well, long before Europeans settled in these parts of the world, the indigenous communities had started producing maple sugar."},{"s":206.27,"e":216.31,"t":"They bored holes in the trunks of maple trees and used containers made of tree bark to collect the liquid sap as it poured out."},{"s":233.07,"e":241.02,"t":"They did this until it turned into sugar, and they were then able to use this to sweeten their food and drinks."},{"s":241.44,"e":249.34,"t":"Since that time, improvements have been made to the process, but it has changed very little overall."},{"s":254.12,"e":258.27,"t":"So let’s look at the production of maple syrup today."},{"s":258.75,"e":265.83,"t":"Clearly, the maple forests are a valuable resource in many Canadian and North American communities."},{"s":266.05,"e":276.61,"t":"The trees have to be well looked after and they cannot be used to make syrup until the trunks reach a diameter of around 25 centimetres."},{"s":276.87,"e":280.32,"t":"This can take anything up to 40 years."},{"s":280.87,"e":288.56,"t":"As I’ve already mentioned, maple trees need the right conditions to grow and also to produce sap."},{"s":288.78,"e":290.13,"t":"Why is this?"},{"s":290.35,"e":300.88,"t":"Well, what happens is that during a cold night, the tree absorbs water from the soil, and that rises through the tree’s vascular system."},{"s":301.21,"e":309.54,"t":"But then in the warmer daytime, the change in temperature causes the water to be pushed back down to the bottom of the tree."},{"s":309.93,"e":319.77,"t":"This continual movement – up and down – leads to the formation of the sap needed for maple syrup production."},{"s":320.05,"e":331.26,"t":"When the tree is ready, it can be tapped and this involves drilling a small hole into the trunk and inserting a tube into it that ends in a bucket."},{"s":331.77,"e":341.63,"t":"The trees can often take several taps, though the workers take care not to cause any damage to the healthy growth of the tree itself."},{"s":342.65,"e":350.84,"t":"The sap that comes out of the trees consists of 98 percent water and 2 percent sugar and other nutrients."},{"s":351.26,"e":362.21,"t":"It has to be boiled so that much of that water evaporates, and this process has to take place immediately, using what are called evaporators."},{"s":362.49,"e":374.22,"t":"These are basically extremely large pans – the sap is poured into these, a fire is built and the pans are then heated until the sap boils."},{"s":374.38,"e":380.43,"t":"As it does this, the water evaporates, and the syrup begins to form."},{"s":397.5,"e":410.22,"t":"After this process, something called ‘sugar sand’ has to be filtered out as this builds up during the boiling and gives the syrup a cloudy appearance and a slightly gritty taste."},{"s":410.3,"e":418.83,"t":"Once this has been done, the syrup is ready to be packaged so that it can be used for a whole variety of products."},{"s":419.15,"e":428.58,"t":"It takes 40 litres of sap to produce one litre of maple syrup so you can get an idea of how much is needed!"},{"s":429.76,"e":432.1,"t":"So that’s the basic process."}]},"ext":"mp3"};
